
import { useState } from 'react';

interface UsedPartImagesProps {
  images: string[];
  name: string;
  condition: string;
}

export default function UsedPartImages({ images, name, condition }: UsedPartImagesProps) {
  const [selectedImage, setSelectedImage] = useState(0);

  return (
    <div>
      <div className="relative w-full h-[460px] bg-gray-100 rounded-lg overflow-hidden mb-3 border border-gray-300">
        <img
          src={images[selectedImage]}
          alt={name}
          className="w-full h-full object-contain object-top"
        />
        <div className="absolute top-3 left-3 bg-yellow-500 text-white text-xs font-bold px-3 py-1 rounded">
          中古品
        </div>
        <div className="absolute top-3 right-3 bg-gray-800/80 text-white text-xs font-bold px-3 py-1 rounded">
          状態：{condition}
        </div>
      </div>
      <div className="flex gap-2">
        {images.map((img, idx) => (
          <button
            key={idx}
            onClick={() => setSelectedImage(idx)}
            className={`w-20 h-20 rounded border-2 overflow-hidden flex-shrink-0 cursor-pointer transition-all ${
              selectedImage === idx
                ? 'border-green-600 shadow-md'
                : 'border-gray-300 hover:border-gray-400'
            }`}
          >
            <img src={img} alt={`${name} ${idx + 1}`} className="w-full h-full object-cover object-top" />
          </button>
        ))}
      </div>
      <p className="text-xs text-gray-500 mt-2 flex items-center gap-1">
        <i className="ri-camera-line w-4 h-4 flex items-center justify-center"></i>
        ※写真は実物を撮影しています。状態は写真でご確認ください。
      </p>
    </div>
  );
}
