
import { Link } from 'react-router-dom';
import { usedParts } from '../../../mocks/products';

interface RelatedUsedPartsProps {
  relatedUsedIds: number[];
}

export default function RelatedUsedParts({ relatedUsedIds }: RelatedUsedPartsProps) {
  const related = usedParts.filter((p) => relatedUsedIds.includes(p.id));

  if (related.length === 0) return null;

  return (
    <div>
      <h2 className="text-lg font-bold text-gray-800 mb-4 flex items-center gap-2 border-b-2 border-green-600 pb-2">
        <i className="ri-recycle-line text-green-600 w-5 h-5 flex items-center justify-center"></i>
        関連中古パーツ
      </h2>
      <div className="grid grid-cols-3 gap-4">
        {related.map((part) => (
          <Link
            key={part.id}
            to={`/used-part/${part.id}`}
            className="bg-white border border-gray-300 rounded-lg p-3 hover:shadow-lg transition-shadow cursor-pointer"
          >
            <div className="relative w-full h-36 bg-gray-100 rounded overflow-hidden mb-3">
              <img src={part.image} alt={part.name} className="w-full h-full object-cover object-top" />
              <div className="absolute top-1 left-1 bg-yellow-500 text-white text-[10px] font-bold px-1.5 py-0.5 rounded">
                中古
              </div>
            </div>
            <div className="flex gap-1 mb-2 flex-wrap">
              {part.tags.map((tag, idx) => (
                <span
                  key={idx}
                  className={`text-xs px-2 py-0.5 rounded whitespace-nowrap ${
                    tag === 'NEW' ? 'bg-red-500 text-white' :
                    tag === '送料込み' ? 'bg-blue-500 text-white' :
                    tag === '送料別' ? 'bg-gray-500 text-white' :
                    tag === '人気' ? 'bg-purple-500 text-white' :
                    'bg-gray-500 text-white'
                  }`}
                >
                  {tag}
                </span>
              ))}
            </div>
            <p className="text-xs text-gray-500">{part.brand}</p>
            <h3 className="text-sm font-bold text-gray-800 mb-1 line-clamp-2">{part.name}</h3>
            <p className="text-lg font-bold text-red-600">¥{part.price.toLocaleString()}</p>
          </Link>
        ))}
      </div>
    </div>
  );
}
