import { useParams, Link } from 'react-router-dom';
import { usedPartDetails } from '../../mocks/usedPartDetails';
import UsedPartImages from './components/UsedPartImages';
import UsedPartInfo from './components/UsedPartInfo';
import RelatedUsedParts from './components/RelatedUsedParts';
import GlobalHeader from '../../components/feature/GlobalHeader';
import GlobalFooter from '../../components/feature/GlobalFooter';
import Breadcrumb from '../../components/feature/Breadcrumb';

export default function UsedPartDetail() {
  const { id } = useParams<{ id: string }>();
  const part = usedPartDetails.find((p) => p.id === Number(id));

  if (!part) {
    return (
      <div className="min-h-screen bg-white flex flex-col items-center justify-center">
        <i className="ri-error-warning-line text-6xl text-gray-300 mb-4"></i>
        <p className="text-xl text-gray-600 mb-4">中古パーツが見つかりませんでした</p>
        <Link to="/" className="bg-green-600 text-white px-6 py-3 rounded-lg font-bold hover:bg-green-700 cursor-pointer whitespace-nowrap">
          トップページへ戻る
        </Link>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-white">
      {/* 共通ヘッダー */}
      <GlobalHeader />

      {/* パンくずリスト */}
      <Breadcrumb items={[
        { label: '中古パーツ', to: '/used-parts' },
        { label: part.brand },
        { label: part.name }
      ]} />

      {/* 商品メインエリア */}
      <main className="max-w-[1400px] mx-auto px-6 pb-8">
        <div className="grid grid-cols-2 gap-10 mb-12">
          <UsedPartImages images={part.images} name={part.name} condition={part.condition} />
          <UsedPartInfo
            brand={part.brand}
            name={part.name}
            price={part.price}
            tags={part.tags}
            sku={part.sku}
            shipping={part.shipping}
            points={part.points}
            stock={part.stock}
            condition={part.condition}
            compatibleVehicles={part.compatibleVehicles}
          />
        </div>

        <div className="grid grid-cols-3 gap-8">
          <div className="col-span-2 space-y-10">
            {/* 商品説明 */}
            <div>
              <h2 className="text-lg font-bold text-gray-800 mb-3 flex items-center gap-2 border-b-2 border-green-600 pb-2">
                <i className="ri-file-text-line text-green-600 w-5 h-5 flex items-center justify-center"></i>
                商品説明
              </h2>
              <p className="text-sm text-gray-700 leading-relaxed">{part.description}</p>
            </div>

            {/* スペック */}
            <div>
              <h2 className="text-lg font-bold text-gray-800 mb-3 flex items-center gap-2 border-b-2 border-green-600 pb-2">
                <i className="ri-list-check text-green-600 w-5 h-5 flex items-center justify-center"></i>
                商品詳細・仕様
              </h2>
              <table className="w-full text-sm">
                <tbody>
                  {part.specs.map((spec, idx) => (
                    <tr key={idx} className={idx % 2 === 0 ? 'bg-gray-50' : 'bg-white'}>
                      <td className="py-3 px-4 font-bold text-gray-700 w-40 border-b border-gray-200">
                        {spec.label}
                      </td>
                      <td className="py-3 px-4 text-gray-600 border-b border-gray-200">
                        {spec.value}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>

            {/* レビュー */}
            <div>
              <h2 className="text-lg font-bold text-gray-800 mb-4 flex items-center gap-2 border-b-2 border-green-600 pb-2">
                <i className="ri-chat-quote-line text-green-600 w-5 h-5 flex items-center justify-center"></i>
                購入者レビュー（{part.reviews.length}件）
              </h2>

              {part.reviews.length > 0 && (
                <div className="flex items-center gap-4 mb-6 bg-amber-50 border border-amber-200 rounded-lg p-4">
                  <div className="text-center">
                    <p className="text-3xl font-bold text-orange-600">
                      {(part.reviews.reduce((sum, r) => sum + r.rating, 0) / part.reviews.length).toFixed(1)}
                    </p>
                    <div className="flex text-yellow-500 text-sm mt-1">
                      {[...Array(5)].map((_, i) => (
                        <i key={i} className={i < Math.round(part.reviews.reduce((sum, r) => sum + r.rating, 0) / part.reviews.length) ? 'ri-star-fill' : 'ri-star-line'}></i>
                      ))}
                    </div>
                    <p className="text-xs text-gray-500 mt-1">{part.reviews.length}件の評価</p>
                  </div>
                  <div className="flex-1">
                    {[5, 4, 3, 2, 1].map((star) => {
                      const count = part.reviews.filter((r) => r.rating === star).length;
                      const pct = part.reviews.length > 0 ? (count / part.reviews.length) * 100 : 0;
                      return (
                        <div key={star} className="flex items-center gap-2 text-xs mb-1">
                          <span className="w-8 text-gray-600 text-right">{star}★</span>
                          <div className="flex-1 bg-gray-200 rounded-full h-2 overflow-hidden">
                            <div className="bg-yellow-500 h-full rounded-full" style={{ width: `${pct}%` }}></div>
                          </div>
                          <span className="w-6 text-gray-500">{count}</span>
                        </div>
                      );
                    })}
                  </div>
                </div>
              )}

              <div className="space-y-4">
                {part.reviews.map((review, idx) => (
                  <div key={idx} className="bg-white border border-gray-200 rounded-lg p-4">
                    <div className="flex items-center justify-between mb-2">
                      <div className="flex items-center gap-2">
                        <div className="w-8 h-8 bg-green-600 rounded-full flex items-center justify-center text-white text-xs font-bold">
                          {review.user.charAt(0)}
                        </div>
                        <span className="text-sm font-bold text-gray-800">{review.user}</span>
                      </div>
                      <span className="text-xs text-gray-500">{review.date}</span>
                    </div>
                    <div className="flex text-yellow-500 text-xs mb-2">
                      {[...Array(5)].map((_, i) => (
                        <i key={i} className={i < review.rating ? 'ri-star-fill' : 'ri-star-line'}></i>
                      ))}
                    </div>
                    <p className="text-sm text-gray-700 leading-relaxed">{review.comment}</p>
                  </div>
                ))}
              </div>
            </div>
          </div>

          <div>
            <RelatedUsedParts relatedUsedIds={part.relatedUsedIds} />

            {/* サイドバナー */}
            <div className="mt-6 space-y-3">
              <div className="bg-gradient-to-r from-green-600 to-emerald-500 p-4 rounded-lg cursor-pointer hover:opacity-90">
                <p className="text-white font-bold text-sm leading-tight">
                  中古パーツ買取<br />高価買取実施中！
                </p>
              </div>
              <div className="bg-gradient-to-r from-orange-500 to-red-500 p-4 rounded-lg cursor-pointer hover:opacity-90">
                <p className="text-white font-bold text-sm leading-tight">
                  今なら取付商品全品<br />+5%ポイント還元
                </p>
              </div>
              <div className="bg-gray-100 border border-gray-300 rounded-lg p-4">
                <h3 className="text-sm font-bold text-gray-800 mb-2 flex items-center gap-1">
                  <i className="ri-shield-check-line text-green-600 w-4 h-4 flex items-center justify-center"></i>
                  中古パーツ安心保証
                </h3>
                <ul className="text-xs text-gray-600 space-y-1">
                  <li className="flex items-start gap-1">
                    <i className="ri-check-line text-green-600 w-3 h-3 flex items-center justify-center mt-0.5"></i>
                    商品到着後7日以内の初期不良対応
                  </li>
                  <li className="flex items-start gap-1">
                    <i className="ri-check-line text-green-600 w-3 h-3 flex items-center justify-center mt-0.5"></i>
                    実物写真で状態を事前確認
                  </li>
                  <li className="flex items-start gap-1">
                    <i className="ri-check-line text-green-600 w-3 h-3 flex items-center justify-center mt-0.5"></i>
                    専門スタッフによる検品済み
                  </li>
                </ul>
              </div>
            </div>
          </div>
        </div>
      </main>

      {/* フッター */}
      <GlobalFooter />
    </div>
  );
}
